-- Catálogo de PRUEBA para validar el RAG (HU-26) y la preselección de recomendaciones. NO es migración ni va a producción.
-- Idempotente: ids fijos aaaaaaaa-0000-0000-0000-0000000000NN.
-- Uso (con el stack local en marcha):
--   docker compose exec -T postgres psql -U skillbridge -d skillbridge < scripts/dev/seed-rag-offerings.sql
--   docker compose exec -T redis redis-cli FLUSHALL        # limpia la caché de ofertas (solo entorno local)
--   docker compose restart backend                         # la carga inicial reindexa las ofertas nuevas
-- Limpieza:
--   DELETE FROM knowledge.knowledge_chunks WHERE source_id LIKE 'offering:aaaaaaaa-0000-0000-0000-%';
--   DELETE FROM offerings WHERE id::text LIKE 'aaaaaaaa-0000-0000-0000-%';

ON CONFLICT (id) DO NOTHING;
